import * as repo from "@/server/repositories/mess/token";
import { applyTokenRules } from "@/server/policy/mess/token";
import { auditWrite } from "@/server/services/audit/write";

export interface TokenInput {
  actorId: string;
  actorRole: string;
  // TODO: add your input fields
}

export interface TokenResult {
  id: string;
  // TODO: add your output fields
}

export async function listToken(input: TokenInput): Promise<TokenResult[]> {
  const decision = applyTokenRules({ action: "list", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);
  return repo.findAll();
}

export async function createToken(input: TokenInput): Promise<TokenResult> {
  const decision = applyTokenRules({ action: "create", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);

  const row = await repo.insert({ createdBy: input.actorId });

  // Audit failures never block the write.
  try {
    await auditWrite({
      action: "TOKEN_CREATED",
      userId: input.actorId,
      details: { id: row.id },
    });
  } catch { /* non-fatal */ }

  return row;
}

export async function deleteToken(id: string, input: TokenInput): Promise<boolean> {
  const decision = applyTokenRules({ action: "delete", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);

  const deleted = await repo.remove(id);

  try {
    await auditWrite({
      action: "TOKEN_DELETED",
      userId: input.actorId,
      details: { id },
    });
  } catch { /* non-fatal */ }

  return deleted;
}
